<?php
namespace Azuriom\Plugin\GamingHubCore\Providers;
use Azuriom\Extensions\Plugin\BaseRouteServiceProvider; use Azuriom\Plugin\GamingHubCore\Controllers\GameController; use Azuriom\Plugin\GamingHubCore\Services\NavbarGameRoutes; use Illuminate\Support\Facades\Route;
class RouteServiceProvider extends BaseRouteServiceProvider { public function loadRoutes():void{Route::middleware('web')->name($this->plugin->id.'.')->group(function(){ $nav=$this->app->make(NavbarGameRoutes::class); foreach($nav->enabledGames() as $g)Route::get('/games/'.$g->slug,[GameController::class,'show'])->defaults('slug',$g->slug)->name(substr($nav->gameRouteName($g),strlen($this->plugin->id)+1)); foreach($nav->enabledServers() as $s)Route::get('/games/'.$s->game->slug.'/'.$s->slug,[GameController::class,'server'])->defaults('game',$s->game->slug)->defaults('server',$s->slug)->name(substr($nav->serverRouteName($s),strlen($this->plugin->id)+1)); require plugin_path($this->plugin->id.'/routes/web.php');});Route::middleware('admin-access')->prefix('admin/'.$this->plugin->id)->name($this->plugin->id.'.admin.')->group(plugin_path($this->plugin->id.'/routes/admin.php'));} }
